"""GCU400 specialization of ``aten::cudnn_affine_grid_generator_backward``.

The shared implementation launches ``grid=(N, num_chunks)``.  GCU caps grid.y at
255, so the 256x256 benchmark shape cannot launch at all: it dies with
``OutOfResources: grid.y, Required: 256, Hardware limit: 255``.  The chunk axis
therefore lives on grid.x here (the batch axis stays on grid.y only while
``N <= 255``).

Three reduction shapes are used, all chosen from measurements on GCU400:

* coefficient path -- for a small plane (``H * W <= 4096``) the six outputs are
  independent, so one program per ``(channel, coefficient)`` pair, ``grid =
  (6, N)``, computes one output each with a single cross-lane reduction.  On GCU
  a cross-lane ``tl.sum`` is the dominant cost of a small plane (six of them cost
  about 3.5us at 1x8x8, where the whole plane is 64 samples), so this beats
  reducing all six in one program: 4.1us vs 6.4us at 1x8x8 and 5.9us vs 8.1us at
  4x64x64.
* channel path -- a plane up to ``16384`` samples is reduced by one program per
  ``(batch element, channel)``, ``grid = (2, N)``: three accumulators and three
  reductions instead of six, and still one launch with no partial buffer.  It
  measured 11.7us against 12.9us for the six-in-one-program form at 8x128x128,
  and the threefold re-read of the coefficient path is what rules that one out
  here (20.6us).
* split path -- larger planes are cut into flat contiguous chunks of BLOCK
  samples, one program each, and a tiny second kernel sums the per-chunk partial
  results.  A flat chunk keeps every load contiguous and measured 2x faster than
  walking the plane row by row (0.0166 ms vs 0.0327 ms at 2x256x256).

The flat sample index has to be split back into ``(h, w)``.  GCU has no integer
divide unit, so power-of-two widths (every training grid) use shift/mask and only
the odd widths fall back to a real division.

float64 is rejected explicitly: GCU has no FP64 unit, so the accumulator would
fail to legalize instead of producing a diagnosable error.
"""

import logging

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn
from flag_gems.utils import libentry
from flag_gems.utils import triton_lang_extension as tle

logger = logging.getLogger(__name__)

# Samples reduced per program in the split path.  8192 measured fastest for the
# large planes that take this path (1024/2048/4096 all landed at 17..34us for
# 2x256x256, 8192 at 15.5us); the 6 accumulators of 8192 lanes are already at the
# register limit, so wider blocks were not tried.
SPLIT_BLOCK = 8192
# 2-byte grids pack two 8192-lane chunks into one program without spilling.
SPLIT_BLOCK_2B = 16384
# Largest block of the single-launch reduce paths.
MAX_BLOCK = 2048
# Planes up to this size are reduced without a second launch, which beats the
# split path once its second launch (~4.5us) is paid for.
SINGLE_PROGRAM_SAMPLES = 16384
# Planes up to this size take the coefficient path (one program per output).  At
# 4x64x64 (4096 samples) it measured 5.9us against 8.1us for six outputs in one
# program; at 8x128x128 (16384 samples) the channel path wins 11.7us to 20.6us.
COEF_SAMPLES = 4096
# Lanes per program on the coefficient path: one chunk covering the plane, from
# 256 lanes up to MAX_BLOCK.
COEF_BLOCK_MIN = 256
# Hardware limit of grid.y (see triton_gcu backend OutOfResources check).
MAX_GRID_Y = 255
# 2 output channels x 3 theta coefficients.
NUM_OUTPUTS = 6
# The six outputs padded to a power of two for the final reduction.
NUM_OUTPUTS_BLOCK = 8


@libentry()
@triton.jit
def _coef_reduce_kernel(
    grad_ptr,
    out_ptr,
    H,
    W,
    HW,
    out_s0,
    out_s1,
    out_s2,
    STEP_X,
    STEP_Y,
    BLOCK: tl.constexpr,
    POW2_W: tl.constexpr,
    LOG_W: tl.constexpr,
    FLAT: tl.constexpr,
):
    """One output of ``grad_theta`` per program.

    ``k`` picks the channel (x or y) and the coefficient (x, y or constant), so
    each program only reduces once instead of six times.  Six programs read the
    plane that one program would have read, which is a loss only once the plane
    is large -- the host only routes small planes here.
    """
    if FLAT:
        # grid.y is capped at 255, so a larger batch folds both axes into grid.x.
        pid = tle.program_id(0)
        k = pid % 6
        n = pid // 6
    else:
        k = tle.program_id(0)
        n = tle.program_id(1)
    channel = k // 3
    coef_index = k % 3

    lane = tl.arange(0, BLOCK)
    acc = tl.zeros([BLOCK], dtype=tl.float32)
    # grad is [N, H, W, 2]: the two channels of a sample are adjacent, so every
    # load is a stride-2 walk over one channel and stays vectorizable.
    plane_ptr = grad_ptr + n * (HW * 2) + channel
    for start in range(0, HW, BLOCK):
        idx = start + lane
        mask = idx < HW
        # GCU has no integer divide unit, so power-of-two widths take shift/mask.
        if POW2_W:
            w = idx & (W - 1)
            h = idx >> LOG_W
        else:
            h = idx // W
            w = idx - h * W
        norm_x = w.to(tl.float32) * STEP_X - 1.0
        norm_y = h.to(tl.float32) * STEP_Y - 1.0
        coef = tl.where(coef_index == 0, norm_x, tl.where(coef_index == 1, norm_y, 1.0))
        acc += tl.load(plane_ptr + idx * 2, mask=mask, other=0.0).to(tl.float32) * coef

    tl.store(
        out_ptr + n * out_s0 + channel * out_s1 + coef_index * out_s2,
        tl.sum(acc, axis=0).to(out_ptr.dtype.element_ty),
    )


@libentry()
@triton.jit
def _channel_reduce_kernel(
    grad_ptr,
    out_ptr,
    H,
    W,
    HW,
    out_s0,
    out_s1,
    out_s2,
    STEP_X,
    STEP_Y,
    BLOCK: tl.constexpr,
    POW2_W: tl.constexpr,
    LOG_W: tl.constexpr,
    FLAT: tl.constexpr,
):
    """Reduce one (batch element, channel) plane into its three theta sums.

    ``grad`` is [N, H, W, 2], so one channel of a sample is a stride-2 walk: every
    element is read exactly once and only three accumulators (hence three
    cross-lane reductions) are live per program.  Compared with reducing both
    channels in one program that halves the reduction count, which is what a plane
    of this size is bound by (11.7us against 12.9us at 8x128x128).
    """
    if FLAT:
        # grid.y is capped at 255, so a larger batch folds both axes into grid.x.
        pid = tle.program_id(0)
        channel = pid % 2
        n = pid // 2
    else:
        channel = tle.program_id(0)
        n = tle.program_id(1)

    lane = tl.arange(0, BLOCK)
    acc_x = tl.zeros([BLOCK], dtype=tl.float32)
    acc_y = tl.zeros([BLOCK], dtype=tl.float32)
    acc_c = tl.zeros([BLOCK], dtype=tl.float32)
    plane_ptr = grad_ptr + n * (HW * 2) + channel
    for start in range(0, HW, BLOCK):
        idx = start + lane
        mask = idx < HW
        # GCU has no integer divide unit, so the power-of-two widths (the shape of
        # every training grid) take the shift/mask form instead.
        if POW2_W:
            w = idx & (W - 1)
            h = idx >> LOG_W
        else:
            h = idx // W
            w = idx - h * W
        norm_x = w.to(tl.float32) * STEP_X - 1.0
        norm_y = h.to(tl.float32) * STEP_Y - 1.0
        value = tl.load(plane_ptr + idx * 2, mask=mask, other=0.0).to(tl.float32)
        acc_x += value * norm_x
        acc_y += value * norm_y
        acc_c += value

    # grad_theta is [N, 2, 3]: channel stride out_s1, coefficient stride out_s2.
    out_base = out_ptr + n * out_s0 + channel * out_s1
    out_dtype = out_ptr.dtype.element_ty
    tl.store(out_base + 0 * out_s2, tl.sum(acc_x, axis=0).to(out_dtype))
    tl.store(out_base + 1 * out_s2, tl.sum(acc_y, axis=0).to(out_dtype))
    tl.store(out_base + 2 * out_s2, tl.sum(acc_c, axis=0).to(out_dtype))


@libentry()
@triton.jit
def _split_reduce_kernel(
    grad_ptr,
    partial_ptr,
    H,
    W,
    HW,
    NUM_CHUNKS,
    STEP_X,
    STEP_Y,
    BLOCK: tl.constexpr,
    BATCH_ON_Y: tl.constexpr,
    POW2_W: tl.constexpr,
    LOG_W: tl.constexpr,
):
    """Reduce one flat chunk of ``BLOCK`` samples into 6 partial sums."""
    chunk = tle.program_id(0)
    if BATCH_ON_Y:
        n = tle.program_id(1)
    else:
        n = chunk // NUM_CHUNKS
        chunk = chunk % NUM_CHUNKS
    # Index of the partial slot; the flat form loses the decoupling of the two
    # program ids, so it is recomputed from the decoded values.
    partial_index = n * NUM_CHUNKS + chunk

    idx = chunk * BLOCK + tl.arange(0, BLOCK)
    mask = idx < HW
    if POW2_W:
        w = idx & (W - 1)
        h = idx >> LOG_W
    else:
        h = idx // W
        w = idx - h * W
    norm_x = w.to(tl.float32) * STEP_X - 1.0
    norm_y = h.to(tl.float32) * STEP_Y - 1.0

    sample_ptr = grad_ptr + n * (HW * 2) + idx * 2
    grad_x = tl.load(sample_ptr, mask=mask, other=0.0).to(tl.float32)
    grad_y = tl.load(sample_ptr + 1, mask=mask, other=0.0).to(tl.float32)

    partial_base = partial_ptr + partial_index * 6
    partial_dtype = partial_ptr.dtype.element_ty
    tl.store(partial_base + 0, tl.sum(grad_x * norm_x, axis=0).to(partial_dtype))
    tl.store(partial_base + 1, tl.sum(grad_x * norm_y, axis=0).to(partial_dtype))
    tl.store(partial_base + 2, tl.sum(grad_x, axis=0).to(partial_dtype))
    tl.store(partial_base + 3, tl.sum(grad_y * norm_x, axis=0).to(partial_dtype))
    tl.store(partial_base + 4, tl.sum(grad_y * norm_y, axis=0).to(partial_dtype))
    tl.store(partial_base + 5, tl.sum(grad_y, axis=0).to(partial_dtype))


@libentry()
@triton.jit
def _reduce_kernel(
    partial_ptr,
    out_ptr,
    NUM_CHUNKS,
    out_s0,
    out_s1,
    out_s2,
    CHUNKS_BLOCK: tl.constexpr,
    OUT_BLOCK: tl.constexpr,
):
    """Sum the per-chunk partial results into the [N, 2, 3] grad_theta.

    The whole ``(num_chunks, 6)`` partial block is loaded at once and reduced
    along the chunk axis, so the six outputs cost one cross-lane reduction
    instead of six: 4.4us against 7.2us at 2x256x256.  ``OUT_BLOCK`` pads the
    six outputs to a power of two.
    """
    n = tle.program_id(0)
    out_index = tl.arange(0, OUT_BLOCK)
    chunk_index = tl.arange(0, CHUNKS_BLOCK)
    offsets = chunk_index[:, None] * 6 + out_index[None, :]
    keep = (out_index[None, :] < 6) & (chunk_index[:, None] < NUM_CHUNKS)
    values = tl.load(partial_ptr + n * NUM_CHUNKS * 6 + offsets, mask=keep, other=0.0)
    sums = tl.sum(values, axis=0)
    tl.store(
        out_ptr + n * out_s0 + (out_index // 3) * out_s1 + (out_index % 3) * out_s2,
        sums.to(out_ptr.dtype.element_ty),
        mask=out_index < 6,
    )


def _cudnn_affine_grid_generator_backward_impl(grad, N, C, H, W, out=None):
    assert grad.dim() == 4, f"grad must be 4D [N, H, W, 2], got {grad.dim()} dims"
    assert grad.shape == (
        N,
        H,
        W,
        2,
    ), f"grad must have shape {(N, H, W, 2)}, got {tuple(grad.shape)}"

    if out is None:
        out = torch.empty((N, 2, 3), dtype=grad.dtype, device=grad.device)

    if N == 0 or H * W == 0:
        out.zero_()
        return out

    if grad.dtype == torch.float64:
        raise NotImplementedError(
            "cudnn_affine_grid_generator_backward: Enflame GCU has no FP64 "
            "support, run the cudnn variant on float32/float16 input instead"
        )

    if not grad.is_contiguous():
        grad = grad.contiguous()

    num_samples = H * W
    out_strides = (out.stride(0), out.stride(1), out.stride(2))
    pow2_w = W == triton.next_power_of_2(W)
    log_w = W.bit_length() - 1
    # align_corners=True steps, clamped so a size-1 axis stays at coordinate -1.
    step_x = 2.0 / max(W - 1, 1)
    step_y = 2.0 / max(H - 1, 1)

    with torch_device_fn.device(grad.device):
        if num_samples <= COEF_SAMPLES:
            # Small plane: one reduction per program, six programs per batch
            # element.  grid.x carries the (channel, coefficient) pair, so the
            # batch axis stays on grid.y while it fits.
            coef_block = min(
                MAX_BLOCK,
                max(COEF_BLOCK_MIN, triton.next_power_of_2(num_samples)),
            )
            grid = (NUM_OUTPUTS, N) if N <= MAX_GRID_Y else (NUM_OUTPUTS * N,)
            _coef_reduce_kernel[grid](
                grad,
                out,
                H,
                W,
                num_samples,
                *out_strides,
                step_x,
                step_y,
                BLOCK=coef_block,
                POW2_W=pow2_w,
                LOG_W=log_w,
                FLAT=(N > MAX_GRID_Y),
            )
            return out

        if num_samples <= SINGLE_PROGRAM_SAMPLES:
            # Medium plane: one program per (batch element, channel), one launch,
            # no second pass.  The plane is kept in one block even when it is
            # smaller than the block, which costs nothing because loads are masked.
            grid = (2, N) if N <= MAX_GRID_Y else (2 * N,)
            _channel_reduce_kernel[grid](
                grad,
                out,
                H,
                W,
                num_samples,
                *out_strides,
                step_x,
                step_y,
                BLOCK=min(MAX_BLOCK, triton.next_power_of_2(num_samples)),
                POW2_W=pow2_w,
                LOG_W=log_w,
                FLAT=(N > MAX_GRID_Y),
            )
            return out

        # A 2-byte element lets one program cover twice as many samples in the
        # same accumulator budget: 16384 lanes measured 12.8us against 15.4us at
        # 2x256x256, while the 4-byte path spills there (41.9us vs 14.3us).
        split_block = SPLIT_BLOCK_2B if grad.element_size() <= 2 else SPLIT_BLOCK
        num_chunks = triton.cdiv(num_samples, split_block)
        chunk_block = triton.next_power_of_2(num_chunks)
        partial = torch.empty(
            (N, num_chunks, NUM_OUTPUTS), dtype=torch.float32, device=grad.device
        )
        # The chunk axis must stay on grid.x: GCU caps grid.y at 255, which is
        # exactly what breaks the shared implementation for large planes.
        batch_on_y = N <= MAX_GRID_Y
        grid = (num_chunks, N) if batch_on_y else (num_chunks * N,)

        _split_reduce_kernel[grid](
            grad,
            partial,
            H,
            W,
            num_samples,
            num_chunks,
            step_x,
            step_y,
            BLOCK=split_block,
            BATCH_ON_Y=batch_on_y,
            POW2_W=pow2_w,
            LOG_W=log_w,
        )
        _reduce_kernel[(N,)](
            partial,
            out,
            num_chunks,
            *out_strides,
            CHUNKS_BLOCK=chunk_block,
            OUT_BLOCK=NUM_OUTPUTS_BLOCK,
        )

    return out


def cudnn_affine_grid_generator_backward(grad, N, C, H, W):
    logger.debug("GEMS_ENFLAMECUDNN_AFFINE_GRID_GENERATOR_BACKWARD")
    return _cudnn_affine_grid_generator_backward_impl(grad, N, C, H, W)


def cudnn_affine_grid_generator_backward_out(grad, N, C, H, W, *, out):
    logger.debug("GEMS_ENFLAMECUDNN_AFFINE_GRID_GENERATOR_BACKWARD_OUT")
    if out is None:
        return _cudnn_affine_grid_generator_backward_impl(grad, N, C, H, W)
    return _cudnn_affine_grid_generator_backward_impl(grad, N, C, H, W, out=out)
